    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint amount, bool isOwner) public payable {
        require(amount > 0 && address(this).balance >= amount);
        if (isOwner) {
            // make this contract the owner by calling a constructor that sets it? We can't. Instead, we delegate ownership setup.
            // We assume the constructor of C has already set the owner to the address passed, so we can't change owner here.
            // To test the owner condition, we need to observe that the call reverts based on sender.
            // We'll rely on the test framework to deploy C with a known owner, and this contract is not the owner.
            // But we must make the rule general over parameters.
        }
        c.f{value: amount}();
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        assert(!isOwner || !reverted); // if isOwner is true (we are the owner), call should not revert. But we cannot change owner at runtime. This won't work.
    }

    receive() external payable {}
}

