contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 ethAmount) public {
        // Restrict to reasonable amount to avoid overflow and keep fuzzer effective
        bound(ethAmount, 0, 1e18 ether);

        // Fund the contract
        vm.deal(address(c), ethAmount);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Owner (this contract) calls withdrawAll, recipient is address(0x1234) (EOA)
        address recipient = address(0x1234);
        c.withdrawAll(recipient);

        // Assert: after withdrawAll, contract balance must be exactly 0
        assertEq(address(c).balance, 0, "Contract balance not zero after withdrawAll");
    }
}

